#Region @DOC
#### Description:
#Copies TI processes from a source database to a target database over the REST API.
#
#### How to Use:
#
#- `pProcess`: REQUIRED: the process name(s) to copy (see patterns below).
#- `pIncludeControlObjects`: 1 = also copy matching control processes (names starting with `}`).
#- `pSourceDatabaseName` / `pTargetDatabaseName`: connection names configured in `}bedrock.session.start`, or connection-details JSON objects returned by it. When a JSON object is passed, that session is reused and is not closed at the end of this process.
#- `pLogOutput`, `pStrictErrorHandling` and `pJson` work as in all bedrock processes.
#
#The object name parameter accepts:
#- a single name, e.g. `Sales`
#- a wildcard pattern, e.g. `Sales*`
#- several names or patterns separated by `&`, e.g. `Sales* & Cost*`
#- a JSON Array of names or patterns, e.g. `["Sales*", "Cost*"]`
#
#> [!IMPORTANT]
#> Processes are created with `POST`, so a process that already exists on the target is not overwritten.
#EndRegion @DOC

### Global Variables
pJson = IF( pJson @= '', '{}', pJson );
StringGlobalVariable(  'sBedrockReturnValue' );
NumericGlobalVariable( 'nBedrockReturnValue' );

### Constants ###
cThisProcName   = GetProcessName();
cUserName       = TM1User();
cTimeStamp      = TimSt( Now, '\Y\m\d\h\i\s' );
cRandomInt      = NumberToString( INT( RAND( ) * 1000000000 ));
cTemp           = cThisProcName |'_'| cTimeStamp |'_'| cRandomInt;
sMessages       = '{"Process": "'|cThisProcName|'", "User": "'|cUsername|'", "Info": ["Process: '''|cThisProcName|''' run by User: '''|cUsername|'''."], "Error": []}';

#################################################################################################
#Region - Process Parameters

pJson = IF( JsonType( pJson ) @<> 'object', '{}', pJson );
sMessages = '{"Process": "'|GetProcessName()|'", "User": "'|TM1User()|'", "Info": ["Process: '''|GetProcessName()|''' run by User: '''|TM1User()|'''."], "Error": []}';
pDefaultParameters = '{
  "pProcess":               null,
  "pSourceDatabaseName":    null,
  "pTargetDatabaseName":    null,
  "pIncludeControlObjects": 0,
  "pLogOutput":             0,
  "pStrictErrorHandling":   0
}';

pPassedParameters = '{
  "pProcess":               '|StringToJson  ( pProcess              )|',
  "pSourceDatabaseName":    '|StringToJson  ( pSourceDatabaseName   )|',
  "pTargetDatabaseName":    '|StringToJson  ( pTargetDatabaseName   )|',
  "pIncludeControlObjects": '|NumberToString( pIncludeControlObjects )|',
  "pLogOutput":             '|NumberToString( pLogOutput             )|',
  "pStrictErrorHandling":   '|NumberToString( pStrictErrorHandling   )|'
}';

pJson = JsonMergePatch( pPassedParameters, pJson );
# String Parameters
pProcess               =                 JsonToString( pJson, '/pProcess'               );
IF( JsonType( JsonGet( pJson, '/pSourceDatabaseName' ) ) @= 'string' );
  pSourceDatabaseName = JsonToString( pJson, '/pSourceDatabaseName' );
ELSE;
  pSourceDatabaseName = JsonGet( pJson, '/pSourceDatabaseName' );
ENDIF;
IF( JsonType( JsonGet( pJson, '/pTargetDatabaseName' ) ) @= 'string' );
  pTargetDatabaseName = JsonToString( pJson, '/pTargetDatabaseName' );
ELSE;
  pTargetDatabaseName = JsonGet( pJson, '/pTargetDatabaseName' );
ENDIF;
# Numeric Parameters
pIncludeControlObjects = StringToNumber( JsonToString( pJson, '/pIncludeControlObjects' ) );
pLogOutput             = StringToNumber( JsonToString( pJson, '/pLogOutput'             ) );
pStrictErrorHandling   = StringToNumber( JsonToString( pJson, '/pStrictErrorHandling'   ) );

### Get the parameters that differ from the default
pDiffer = JsonDiff( pDefaultParameters, pJson );
nSize = JsonSize( pDiffer );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  pDiffer = JsonReplace( pDiffer, '/'|NumberToString( nSize )|'/op', '"add"' );
END;
pJson = JsonPatch( '{}', pDiffer );

### LogOutput parameters
nSize = JsonSize( pJson );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  sKey = JsonGetKey( pJson, nSize );
  pPassedParameters = JsonReplace( pPassedParameters, sKey, JsonGet( pJson, sKey ) );
END;

sMessages = JsonAdd( sMessages, '/Info/0', pPassedParameters );
IF( pLogOutput = 1 );
  LogOutput('INFO', JsonToString( sMessages, '/Info/0' ) );
ENDIF;

#EndRegion - Process Parameters
#################################################################################################

#################################################################################################
#Region - Validate Parameters

# Get Database Connection Details
sSourceDatabaseParameterType = JsonType( pSourceDatabaseName );
IF( sSourceDatabaseParameterType @<> 'object' );
  ExecuteProcess( '}bedrock.session.start', 'pConnectionName', pSourceDatabaseName, 'pJson', pJson ); sSourceConnectionDetails = sBedrockReturnValue;
ELSE;
  sSourceConnectionDetails = pSourceDatabaseName;
ENDIF;
pJson = JsonAdd( pJson, 'pSourceDatabaseName', sSourceConnectionDetails );

sTargetDatabaseParameterType = JsonType( pTargetDatabaseName );
IF( sTargetDatabaseParameterType @<> 'object' );
  ExecuteProcess( '}bedrock.session.start', 'pConnectionName', pTargetDatabaseName, 'pJson', pJson ); sTargetConnectionDetails = sBedrockReturnValue;
ELSE;
  sTargetConnectionDetails = pTargetDatabaseName;
ENDIF;
pJson = JsonAdd( pJson, 'pTargetDatabaseName', sTargetConnectionDetails );

### Authentication headers for requests to this connection
sSrcAuthHeaders = '[]';
IF( JsonToString( sSourceConnectionDetails, '/sAuthHeader' ) @<> '' );
  sSrcAuthHeaders = JsonAdd( sSrcAuthHeaders, '', StringToJson( 'Authorization: ' | JsonToString( sSourceConnectionDetails, '/sAuthHeader' ) ) );
ELSEIF( JsonToString( sSourceConnectionDetails, '/sSID' ) @<> '' );
  sSrcAuthHeaders = JsonAdd( sSrcAuthHeaders, '', StringToJson( 'Cookie: ' | JsonToString( sSourceConnectionDetails, '/sSID' ) ) );
ENDIF;

### Authentication headers for requests to this connection
sTgtAuthHeaders = '[]';
IF( JsonToString( sTargetConnectionDetails, '/sAuthHeader' ) @<> '' );
  sTgtAuthHeaders = JsonAdd( sTgtAuthHeaders, '', StringToJson( 'Authorization: ' | JsonToString( sTargetConnectionDetails, '/sAuthHeader' ) ) );
ELSEIF( JsonToString( sTargetConnectionDetails, '/sSID' ) @<> '' );
  sTgtAuthHeaders = JsonAdd( sTgtAuthHeaders, '', StringToJson( 'Cookie: ' | JsonToString( sTargetConnectionDetails, '/sSID' ) ) );
ENDIF;

IF( JsonSize( pProcess ) = -1 );
  ExecuteProcess( '}bedrock.utils.string.to_list', 'pString', pProcess, 'pDelimiter', '&', 'pTRIM', 1 );
  pProcess = sBedrockReturnValue;
ENDIF;

### If errors occurred terminate process with a major error status ###
IF( JsonSize( sMessages, '/Error' ) <> 0 );
  IF( pStrictErrorHandling = 1 );
    ProcessQuit;
  ELSE;
    ProcessBreak;
  ENDIF;
ENDIF;

#EndRegion - Validate Parameters
#################################################################################################

#################################################################################################
#Region - Setup Execute Http Request Parameters

# Get Database Source Details
sSourceURL = JsonToString( JsonGet( sSourceConnectionDetails, 'sURL' ) );
sSourceVer = JsonToString( JsonGet( sSourceConnectionDetails, 'sVer' ) );

# Get Database Target Details
sTargetURL = JsonToString( JsonGet( sTargetConnectionDetails, 'sURL' ) );
sTargetVer = JsonToString( JsonGet( sTargetConnectionDetails, 'sVer' ) );

# Get the process error directory, because Bedrock 4 defaults to it.
IF( StringToNumber( SUBST( sSourceVer, 1, 2 ) ) < 12 );
  sSrcDir = 'ERROR - Did not get directory for database with version <12.';
ELSE;
  sSrcDir = '.';
ENDIF;

IF( StringToNumber( SUBST( sTargetVer, 1, 2 ) ) < 12 );
  sTgtDir = 'ERROR - Did not get directory for database with version <12.';
ELSE;
  sTgtDir = '.';
ENDIF;

# Create Parameters for }bedrock.hier.export and }bedrock.hier.import
sParameters = '{
  "pTgtDir": '|StringToJson( sSrcDir )|', 
  "pSrcDir": '|StringToJson( sTgtDir )|', 
  "pDelim": ",",
  "pTitleRecord": 0
}';
pJson = JsonAdd( pJson, 'pProcessParameters', sParameters );

#EndRegion - Setup Execute Http Request Parameters
#################################################################################################

#################################################################################################
#Region - Create Datasource

# Get Processes that match pProcess
sProcessMDX = '';
nCount = JsonSize( pProcess );
WHILE( nCount > 0 );
  nCount = nCount - 1;
  sProcess = JsonToString( JsonGet( pProcess, nCount ) );

  sProcessMDX = sProcessMDX | ', {TM1FILTERBYPATTERN(TM1SUBSETALL([}Processes].[}Processes]), "'|sProcess|'")}';
END;
sProcessMDX = '{DISTINCT({'|DELET( sProcessMDX, 1, 2 )|'})}'  ;

# Remove Control Objects
IF( pIncludeControlObjects = 0 );
  sProcessMDX = '{EXCEPT('|sProcessMDX|', {TM1FILTERBYPATTERN({TM1SUBSETALL([}Processes].[}Processes])},"}*")})}';
ENDIF;

# Create Processes Subset
ExecuteProcess('}bedrock.process.execute_http_request',
  'pMethod', 'POST',
  'pURL', sSourceURL | '/ExecuteMDXSetExpression?$expand=Tuples($expand=Members($select=Name))',
  'pBody', '{"MDX":'|StringToJson( sProcessMDX )|'}',
  'pHeaders', JsonAdd( sSrcAuthHeaders, '', '"Content-Type:application/json; charset=utf-8"' ),
  'pResponseFile', cTemp|'.blb',
  'pJson', pJson );

# Datasource Parameters
DatasourceType = 'JSON';
DatasourceJsonRootPointer = '/Tuples';
DatasourceJsonVariableMapping = '{
  "vProcess": "/Members/0/Name"
}';
DatasourceNameForServer = cTemp|'.blb';




#EndRegion - Create Datasource
#################################################################################################

EpilogProcedure:
#****Begin: Generated Statements***
#****End: Generated Statements****

##################################################################################################
##Region - Cleanup

IF( FileExists( cTemp|'.blb' ) = 1 );
  ASCIIDelete( cTemp|'.blb' );
ENDIF;

IF( sSourceDatabaseParameterType @<> 'object' );
  ExecuteProcess('}bedrock.process.execute_http_request',
    'pMethod', 'POST',
    'pURL', sSourceURL | '/ActiveSession/tm1.Close',
    'pHeaders', JsonAdd( sSrcAuthHeaders, '', '"Content-Type:application/json; charset=utf-8"' ),
    'pJson', pJson 
  );
ENDIF;

IF( sTargetDatabaseParameterType @<> 'object' );
  ExecuteProcess('}bedrock.process.execute_http_request',
    'pMethod', 'POST',
    'pURL', sTargetURL | '/ActiveSession/tm1.Close',
    'pHeaders', JsonAdd( sTgtAuthHeaders, '', '"Content-Type:application/json; charset=utf-8"' ),
    'pJson', pJson 
  );
ENDIF;

#EndRegion - Cleanup
#################################################################################################
